/* -- construction --
 * T1-8 (pipeline Track 1): RECOMP_XMM_INTRIN 1 builds each value in one
 * SSE register and writes the union with ONE 16-byte store. The lane-wise
 * form (0) writes it with two 8-byte (or four 4-byte) stores, and the
 * 16-byte reload that follows every movss/movsd/movups then misses store
 * forwarding (~10+ cycles each in the hot SSE code). Same bits in every
 * lane: _mm_set_ss/_mm_set_sd/_mm_cvtsi32_si128 zero the upper lanes as
 * movss/movsd/movd do, and nothing is converted. The union is unchanged
 * (prebuilt objects share it). Self-test: recomp_xmm_selftest()
 * (recomp_dispatch.c), [XMM-SELFTEST] at startup. Build-time switch only;
 * 0 = the lane-wise C below, token for token as before. */
#ifndef RECOMP_XMM_INTRIN
#if defined(_M_X64) || defined(__x86_64__) || defined(__SSE2__)
#define RECOMP_XMM_INTRIN 1
#define RECOMP_XMM_INTRIN 0
#if RECOMP_XMM_INTRIN
#include <emmintrin.h>

#if RECOMP_XMM_INTRIN
    RecompXmm r; _mm_storeu_ps(r.f, _mm_setzero_ps()); return r;
}

    RecompXmm r; _mm_storeu_ps(r.f, _mm_set_ss(v)); return r;
}

    RecompXmm r; _mm_storeu_pd(r.d, _mm_set_sd(v)); return r;
}

    RecompXmm r; _mm_storeu_si128((__m128i *)r.u, _mm_cvtsi32_si128((int)bits)); return r;
}
 * access. Done lane-wise, which is also unaligned-safe for movups.
 * With RECOMP_XMM_INTRIN the 4 loads are the same (same order, same
 * accessor); only the union is written with one 16-byte store. */
#if RECOMP_XMM_INTRIN
    uint32_t u0 = MEM32(addr), u1 = MEM32(addr + 4), u2 = MEM32(addr + 8), u3 = MEM32(addr + 12);
    _mm_storeu_si128((__m128i *)r.u, _mm_setr_epi32((int)u0, (int)u1, (int)u2, (int)u3));
/* T1-2 (pipeline Track 1): how an indirect-call target is resolved.
 * RECOMP_ICALL_RESOLVE is the old chain (manual overrides, then the dispatch
 * table) and is what every file uses unless it redefines it. FastCode copies
 * (tools/fastcode.py, recomp_fast_*.c) redefine it as RECOMP_ICALL_RESOLVE_FLAT:
 * one inline probe of the flat table recomp_dispatch_fast_init() exports,
 * skipping VAs that have a manual override (bit set in g_icall_flat_ovr);
 * a NULL from the probe falls back to the old chain, so the result is the same
 * by construction. g_icall_flat_span stays 0 (probe off) unless FastCode is on. */
#ifndef RECOMP_ICALL_RESOLVE
#define RECOMP_ICALL_RESOLVE(_fn, _va) do { \
    (_fn) = recomp_lookup_manual(_va); \
    if (!(_fn)) (_fn) = recomp_lookup(_va); \
} while (0)
extern void (**g_icall_flat_tab)(void); /* recomp_func_t *, spelled out: recomp_dispatch.c has its own typedef */
extern const uint8_t *g_icall_flat_ovr;
extern uint32_t g_icall_flat_base, g_icall_flat_span;
int recomp_dispatch_fast_init(void);
#define RECOMP_ICALL_RESOLVE_FLAT(_fn, _va) do { \
    uint32_t _fo = (uint32_t)(_va) - g_icall_flat_base; \
    (_fn) = (recomp_func_t)0; \
    if (_fo < g_icall_flat_span && !(g_icall_flat_ovr[_fo >> 3] & (1u << (_fo & 7u)))) \
        (_fn) = (recomp_func_t)g_icall_flat_tab[_fo]; \
    if (!(_fn)) { \
        (_fn) = recomp_lookup_manual(_va); \
        if (!(_fn)) (_fn) = recomp_lookup(_va); \
} while (0)

/* T1-2 FastCode switch ([Cpu] FastCode / RECOMP_FASTCODE, read once in main.c
 * before any guest code runs). tools/fastcode.py puts RECOMP_FAST_ENTRY at the
 * top of each function that has a fast copy: off = the original body runs
 * unchanged; on = it tail-calls the copy. */
extern int g_recomp_fastcode;
#define RECOMP_FAST_ENTRY(f) do { \
    extern void f##__fast(void); \
    if (g_recomp_fastcode) { f##__fast(); return; } \
} while (0)

